using System.Security.Claims;
using Microsoft.AspNetCore.Authentication;
using Microsoft.AspNetCore.Authentication.Cookies;
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Authorization;
using Microsoft.EntityFrameworkCore;
using StockWise.Data;
using StockWise.Models;
namespace StockWise.Controllers;
public class AccountController : Controller { private readonly AppDbContext _db; private readonly PasswordHasher<AppUser> _hasher = new(); public AccountController(AppDbContext db) => _db=db; [AllowAnonymous] public async Task<IActionResult> Setup(){if(await _db.Users.AnyAsync())return RedirectToAction(nameof(Login));return View();} [HttpPost,AllowAnonymous,ValidateAntiForgeryToken] public async Task<IActionResult> Setup(string username,string password,string confirmPassword){if(await _db.Users.AnyAsync())return RedirectToAction(nameof(Login));if(string.IsNullOrWhiteSpace(username)||username.Length>60)ModelState.AddModelError("username","Username is required (maximum 60 characters).");if(string.IsNullOrWhiteSpace(password)||password.Length<10)ModelState.AddModelError("password","Use a password with at least 10 characters.");if(password!=confirmPassword)ModelState.AddModelError("confirmPassword","Passwords do not match.");if(!ModelState.IsValid)return View();var user=new AppUser{Username=username.Trim(),Role="Admin",CreatedAtUtc=DateTime.UtcNow};user.PasswordHash=_hasher.HashPassword(user,password);_db.Users.Add(user);await _db.SaveChangesAsync();TempData["Success"]="Admin account created. Please sign in.";return RedirectToAction(nameof(Login));} [AllowAnonymous] public IActionResult Login() => User.Identity?.IsAuthenticated == true ? RedirectToAction("Index","Home") : View(); [HttpPost,AllowAnonymous,ValidateAntiForgeryToken] public async Task<IActionResult> Login(string username,string password) { var user=await _db.Users.SingleOrDefaultAsync(u=>u.Username==username); if(user==null || _hasher.VerifyHashedPassword(user,user.PasswordHash,password)==PasswordVerificationResult.Failed) { ModelState.AddModelError("", "Invalid username or password."); return View(); } var claims=new List<Claim>{new(ClaimTypes.Name,user.Username),new(ClaimTypes.Role,user.Role)}; await HttpContext.SignInAsync(CookieAuthenticationDefaults.AuthenticationScheme,new ClaimsPrincipal(new ClaimsIdentity(claims,CookieAuthenticationDefaults.AuthenticationScheme))); return RedirectToAction("Index","Home"); } [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Logout(){await HttpContext.SignOutAsync(CookieAuthenticationDefaults.AuthenticationScheme);return RedirectToAction(nameof(Login));} public IActionResult Denied()=>Content("Access denied."); }
